import os
import sys
import subprocess
import json
import argparse
import shlex

def run_commands(file_path):
    results = []
    try:
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if not line:
                    continue
                try:
                    command = shlex.split(line)
                    result = subprocess.run(
                        command,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.STDOUT,
                        text=True,
                        check=False
                    )
                    output = result.stdout
                    exit_code = result.returncode
                    results.append({
                        "command": line,
                        "exit_code": exit_code,
                        "output": output
                    })
                except Exception as e:
                    results.append({
                        "command": line,
                        "exit_code": -1,
                        "output": f"Error executing command: {str(e)}"
                    })
    except IOError:
        print(f"Error: Could not read file {file_path}", file=sys.stderr)
        sys.exit(2)
    return results

def send_notification(results):
    webhook_url = os.getenv('BUILD_WEBHOOK_URL')
    if not webhook_url:
        print("Error: BUILD_WEBHOOK_URL environment variable not set", file=sys.stderr)
        sys.exit(1)

    payload = {
        "results": results
    }

    try:
        import requests
        response = requests.post(
            webhook_url,
            data=json.dumps(payload),
            headers={'Content-Type': 'application/json'}
        )
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f"Error sending notification: {str(e)}", file=sys.stderr)
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description='Run commands and notify via webhook.')
    parser.add_argument('file_path', help='Path to the text file of commands')
    args = parser.parse_args()

    results = run_commands(args.file_path)

    all_success = all(result['exit_code'] == 0 for result in results)
    if not all_success:
        sys.exit(1)

    send_notification(results)

if __name__ == "__main__":
    main()

