import sys
import os
import subprocess
import json
import requests

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_and_notify.py <commands_file>", file=sys.stderr)
        sys.exit(2)

    commands_file = sys.argv[1]
    if not os.path.exists(commands_file):
        print(f"Error: File '{commands_file}' does not exist.", file=sys.stderr)
        sys.exit(2)

    results = []
    with open(commands_file, 'r') as f:
        for line in f:
            stripped_line = line.strip()
            if not stripped_line:
                continue

            command = stripped_line.rstrip('\n')
            try:
                result = subprocess.run(
                    command,
                    shell=True,
                    check=False,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True
                )
                output = result.stdout + result.stderr
                results.append({
                    "command": command,
                    "exit_code": result.returncode,
                    "output": output
                })
            except Exception as e:
                print(f"Error executing command '{command}': {e}", file=sys.stderr)
                results.append({
                    "command": command,
                    "exit_code": -1,
                    "output": f"Error executing command: {str(e)}"
                })

    all_passed = all(r["exit_code"] == 0 for r in results)
    sys.exit(1 if not all_passed else 0)

    if "BUILD_WEBHOOK_URL" not in os.environ:
        print("Error: BUILD_WEBHOOK_URL environment variable not set.", file=sys.stderr)
        sys.exit(1)

    try:
        url = os.environ["BUILD_WEBHOOK_URL"]
        payload = {
            "results": results
        }
        response = requests.post(url, json=payload, headers={"Content-Type": "application/json"})
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f"Error sending results to webhook: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import os
import sys
import subprocess
import json
import requests
from typing import List, Dict, Any

def run_commands_from_file(file_path: str) -> List[Dict[str, Any]]:
    results = []
    try:
        with open(file_path, 'r') as file:
            for line in file:
                stripped_line = line.strip()
                if not stripped_line:
                    continue
                try:
                    result = subprocess.run(
                        stripped_line,
                        shell=True,
                        check=True,
                        text=True,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE
                    )
                    output = result.stdout + result.stderr
                    results.append({
                        "command": stripped_line.rstrip('\n'),
                        "exit_code": result.returncode,
                        "output": output
                    })
                except subprocess.CalledProcessError as e:
                    output = e.stdout + e.stderr
                    results.append({
                        "command": stripped_line.rstrip('\n'),
                        "exit_code": e.returncode,
                        "output": output
                    })
    except IOError:
        print(f"Error: Could not read file {file_path}", file=sys.stderr)
        sys.exit(2)
    return results

def send_notification(results: List[Dict[str, Any]]) -> None:
    if not results:
        return
    webhook_url = os.getenv('BUILD_WEBHOOK_URL')
    if not webhook_url:
        return

    payload = {
        "results": results
    }
    try:
        response = requests.post(webhook_url, json=payload, headers={'Content-Type': 'application/json'})
        response.raise_for_status()
    except requests.RequestException as e:
        print(f"Failed to send notification: {e}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python run_and_notify.py <commands_file>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    results = run_commands_from_file(file_path)

    if any(result['exit_code'] != 0 for result in results):
        sys.exit(1)

    send_notification(results)
    sys.exit(0)

if __name__ == "__main__":
    main()
